def fit_standardizer(train_values):
    if not train_values:
        raise ValueError('training values required')
    mean = sum(train_values) / len(train_values)
    variance = sum((x - mean) ** 2 for x in train_values) / len(train_values)
    return {'mean': mean, 'std': variance ** 0.5 or 1.0}
